// Списки данных
const locations = ['Супермаркет', 'Космическая станция', 'Древний замок', 'Офис будущего', 'Таинственный лес', 'Подводная лодка', 'Пустыня', 'Школа магии', 'Заброшенный завод', 'Пляж'];
const styles = ['Мультяшный', 'Реализм', 'Аниме', 'Киберпанк', 'Пиксель-арт', '3D Рендер', 'Скетч', 'Масляная живопись', 'Нуар', 'Стимпанк'];
const languages = ['русский', 'английский'];
const allCharacters = [
  'Кассир', 'Консультант', 'Менеджер', 'Охранник', 'Покупатель', 'Робот', 'Пришелец', 'Рыцарь', 'Маг', 'Детектив',
  'Пират', 'Ниндзя', 'Ученый', 'Астронавт', 'Зомби', 'Дракон', 'Король', 'Шпион', 'Врач', 'Повар',
  'Механик', 'Художник', 'Спортсмен', 'Турист', 'Пилот', 'Фермер', 'Бармен', 'Музыкант', 'Судья', 'Лесник'
];

// Функция для получения рандомных элементов (нужна для строк)
const getRandom = (arr) => arr[Math.floor(Math.random() * arr.length)];

// Логика для персонажей
const shuffledChars = [...allCharacters].sort(() => 0.5 - Math.random());
const charCount = Math.floor(Math.random() * (6 - 3 + 1)) + 3; 
const selectedCharacters = shuffledChars.slice(0, charCount).join(', ');

// Логика для победителя (true/false)
const spyWinner = Math.random() >= 0.5;

return [
  {
    json: {
      params: {},
      query: {},
      body: {
        location: getRandom(locations),
        Style: getRandom(styles),
        Characters: selectedCharacters,
        Language: getRandom(languages),
        type_query: "Card" // Исправлено: передаем готовый true/false
      },
      webhookUrl: 'https://n8n.sharksbots.com/webhook-test/get-scene-picture',
      executionMode: 'test',
    },
  },
];

