for (const item of $input.all()) {
  // 1. Получаем данные из входящего JSON
  // Пытаемся взять данные из item.json или item.json.body (если пришла строка)
  let data = item.json.body;
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      data = item.json; // Если не распарсилось, берем верхний уровень
    }
  } else {
    data = item.json; // Данные уже на верхнем уровне
  }

  // Задаем значения по умолчанию, если данные не пришли
  const location = data.location || 'Подземелье';
  const roles_list = (data.roles || ['Авантюрист', 'Маг', 'Страж']).join(', ');
  const style = data.generation_style || 'как настоящее фото';

  // Входная переменная "spywon" (ожидаем строку "true" или "false")
  const spywon_status = String(data.spywon).toLowerCase() || "false";

  let final_prompt = '';

  // Описание шпиона (для вставки в оба варианта промта)
  const spy_description = `черная безликая фигура в черной шляпе, с черным револьвером на поясе и с белым вопросительном знаке на груди - это шпион`;

  // Обязательные ограничения (добавляются в конец любого промта)
  const final_constraints = ` ! Что НЕ должно присутствовать на изображении: 1. НИКАКОГО ТЕКСТА! 2. на изображении не должно быть никаких людей кроме тех кто прописан выше.`;

  // === ЛОГИКА ВЫБОРА ПРОМТА ===

  if (spywon_status === "true") {
    // Вторая переменная: ШПИОН ВЫИГРАЛ (Ваш новый текст)
    final_prompt = `Твоя главная задача: сгенерировать картинку. Ниже будут данные о этой картинке. Изображение будет служить игре по типу Шпион. 1. Локация изображение должна быть строго: ${location}. 2. На картинке должны присутствовать данные люди с ролями: ${roles_list}, а так же ${spy_description}. Шпион должен насмехаться над другими людьмы с ролями (его не рассекретили). Он стоит в позе триумфатора, пока другие люди (роли: ${roles_list}) выглядят растерянными и обманутыми. 3. Изображение должно быть строго в конкретном стиле, поэтому адаптируй картинку под этот стиль: ${style}.`;
  } else {
    // Первая переменная: ШПИОН ПРОИГРАЛ (Текст из прошлого запроса)
    final_prompt = `Твоя главная задача: сгенерировать картинку. Ниже будут данные о этой картинке. Изображение будет служить игре по типу Шпион. 1. Локация изображение должна быть строго: ${location}. 2. На картинке должны присутствовать данные люди с ролями: ${roles_list}, а так же ${spy_description}. Остальные люди с ролями должны его запинывать (жестоко избивать руками и ногами) за то что рассекретили его. Шпион лежит на земле, скрутившись от боли, остальные роли (роли: ${roles_list}) окружили его. 3. Изображение должно быть строго в конкретном стиле, поэтому адаптируй картинку под этот стиль: ${style}.`;
  }

  // Добавляем обязательные ограничения
  final_prompt += final_constraints;

  // === СОХРАНЕНИЕ РЕЗУЛЬТАТА В JSON ===
  item.json.Prompt = final_prompt; // Результат будет доступен как $json.Prompt
  item.json.spywon_status = spywon_status; // Сохраняем статус для отладки

  // === ВАЖНО: СОХРАНЯЕМ БИНАРНЫЕ ДАННЫЕ (ФОТОГРАФИИ) ===
  if (item.binary && item.binary.data) {
    // Убедимся, что файл назван 'data', чтобы Gemini его увидел
    const firstKey = Object.keys(item.binary)[0];
    if (firstKey !== 'data') {
      item.binary.data = item.binary[firstKey];
    }
  }
}

// Возвращаем все элементы с сохраненными фото и новым полем Prompt
return $input.all();

