return items.map(item => {
  const body = item.json.body || {};

  // 1. Работаем с ролями
  const roleKeys = Object.keys(body)
    .filter(key => key.startsWith('roles['))
    .sort((a, b) => {
      return a.localeCompare(b, undefined, { numeric: true });
    });

  // Создаем массив только из названий профессий для roles_list
  const rolesArray = roleKeys.map(key => body[key]);
  const roles_list = rolesArray.join(', ');

  // Формируем части для лиц персонажей
  const facesParts = roleKeys.map((key, index) => {
    const roleName = body[key];
    return `для ${roleName} лицо photo_${index}`;
  });

  // Собираем строку лиц и добавляем в конец фразу про шпиона
  let faces_for_role = facesParts.join(', ');
  if (faces_for_role) {
    faces_for_role += ', '; // добавляем запятую, если список ролей не пустой
  }
  faces_for_role += 'для персонажа шпиона используй лицо из картинки spy_photo';

  // 2. Логика для статуса шпиона
  const spyWinnerPromtStr = `Твоя главная задача: сгенерировать картинку по опсанию сцены 
1. Сцена: черная безликая фигура в черной шляпе, и с белым вопросительном знаке на груди - это шпион. Шпион должен насмехаться над другими людьмы (персонажами) с (его не рассекретили). Он стоит в позе триумфатора, пока другие люди (персонажи) выглядят растерянными и обманутыми.`;

  const spyLoserPromtStr = `Твоя главная задача: сгенерировать картинку по опсанию сцены 
1. Сцена: Наглый но расстореный человек полностью в черной одежде в черной шляпе, - это шпион. Остальные люди (персонажи) показывать на него пальцем, стоят вокруг него и хохочут над ним потому что рассекретили`;

  const isSpyWin = String(body.spy_is_win).toLowerCase() === 'true';
  const promt_situation = isSpyWin ? spyWinnerPromtStr : spyLoserPromtStr;

  // 3. Формируем итоговый объект JSON
  const newJson = {
    ...body,
    roles_count: roleKeys.length,
    roles_list: roles_list,
    faces_for_role: faces_for_role,
    promt_situation: promt_situation
  };

  return {
    json: newJson,
    binary: item.binary 
  };
});

